def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if tz is None:
        return datetime.time(nanoseconds // 3600000000000,
                             (nanoseconds // 60000000000) % 60,
                             (nanoseconds // 1000000000) % 60,
                             nanoseconds % 1000000000
                             )
    else:
        return datetime.time(nanoseconds // 3600000000000,
                             (nanoseconds // 60000000000) % 60,
                             (nanoseconds // 1000000000) % 60,
                             nanoseconds % 1000000000,
                             tz=tz)

