def point_type(name, fields, srid_map):
        """ Dynamically create a Point subclass.
        """
        def __init__(self, *args, **kwargs):
            # Initialize the base class
            point_dict = {}
            for i, field_name in enumerate(fields):
                if i < len(args):
                    point_dict[field_name] = args[i]
                elif field_name in kwargs:
                    point_dict[field_name] = kwargs[field_name]
                else:
                    raise ValueError(f"Missing value for field '{field_name}'")
            self.point_dict = point_dict
            # Set SRID if provided
            if 'srid' in kwargs:
                self.srid = kwargs['srid']
            else:
                self.srid = srid_map.get(name, None)

        def __repr__(self):
            field_values = ", ".join(f"{f}={self.point_dict[f]}" for f in fields)
            srid_str = f", srid={self.srid}" if hasattr(self, 'srid') and self.srid else ""
            return f"{name}({field_values}{srid_str})"

        def __eq__(self, other):
            if not isinstance(other, type(self)):
                return False
            if not hasattr(other, 'point_dict'):
                return False
            if (hasattr(self, 'srid') and hasattr(other, 'srid')) and self.srid != other.srid:
                return False
            return self.point_dict == other.point_dict

        def __hash__(self):
            srid_hash = hash(self.srid) if hasattr(self, 'srid') and self.srid else 0
            return hash((tuple(self.point_dict[f] for f in fields), srid_hash))

        # Create the class dynamically
        attributes = {
            '__init__': __init__,
            '__repr__': __repr__,
            '__eq__': __eq__,
            '__hash__': __hash__,
            '__slots__': [f for f in fields] + ['point_dict', 'srid'],
        }
        return type(name, (Point,), attributes)

