def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class _Point:
        pass

    for field_name, field_def in fields.items():
        if field_name in srid_map:
            field_type = srid_map[field_name]['type']
            field_srid = srid_map[field_name]['srid']
        else:
            field_type = field_def['type']
            field_srid = None

        if field_type == 'point':
            _Point._field_{}.format(field_name) = field_type
            _Point._srid_{}.format(field_name) = field_srid

    _Point.__name__ = name
    return _Point
