class OrderedDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.__order = []

    def __setitem__(self, key, value):
        if key not in self:
            self.__order.append(key)
        super().__setitem__(key, value)

    def __getitem__(self, key):
        result = super().__getitem__(key)
        if key in self.__order:
            self.__order.remove(key)
            self.__order.append(key)
        return result

    def __delitem__(self, key):
        super().__delitem__(key)
        if key in self.__order:
            self.__order.remove(key)

    def __len__(self):
        return len(super())

    def __iter__(self):
        return iter(self.__order)

    def __reversed__(self):
        return reversed(self.__order)

    def __contains__(self, key):
        return super().__contains__(key)

    def get(self, key, default=None):
        if key in self:
            self.move_to_end(key)
            return super().__getitem__(key)
        return default

    def pop(self, key, *args, **kwargs):
        result = super().pop(key, *args, **kwargs)
        if key in self.__order:
            self.__order.remove(key)
        return result

    def popitem(self, last=True):
        if last:
            key = self.__order.pop()
        else:
            key = self.__order.pop(0)
        value = super().__getitem__(key)
        del self[key]
        return (key, value)

    def setdefault(self, key, default=None):
        if key not in self:
            self.__order.append(key)
        return super().__setitem__(key, default) if key not in self else super().__getitem__(key)

    def update(self, *args, **kwargs):
        super().update(*args, **kwargs)
        for key in self.__order:
            if key not in super():
                self.__order.remove(key)

    def move_to_end(self, key, last=True):
        if key not in self.__order:
            raise KeyError(key)
        self.__order.remove(key)
        if last:
            self.__order.append(key)
        else:
            self.__order.insert(0, key)

