def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    return [c for i, c in enumerate(classes) if c not in classes[:i]]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        if cls not in result:
            # Check if cls is a subclass of any class already in result
            # If so, it's redundant
            if not any(issubclass(cls, existing) for existing in result):
                result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for base in classes:
        if all(not issubclass(base, other) for other in result):
            result.append(base)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = set()
    for cls in classes:
        if cls not in result:
            result.add(cls)
            result.difference_update(cls.__bases__)
    return list(result)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    min_classes = []
    for cls in classes:
        if cls not in min_classes and not any(is subclass(cls, other) for other in classes if other != cls):
            min_classes.append(cls)
    return min_classes

