def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    for key, value in self.properties.items():
        if key not in ('E', 't'):
            continue
        if key not in context['value']:
            context['value'][key] = {}
        context['value'][key].update(value)
    for key, value in self.errors.items():
        if key not in context['error']:
            context['error'][key] = {}
        context['error'][key].update(value)

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Map field names to coordinate names
        field_to_coord = {
            "E": "x",
            "t": "y",
            "z": "z"
        }

        # Update context.value with this graph's values
        for field in self.fields:
            coord = field_to_coord.get(field)
            if coord:
                if coord not in context['value']:
                    context['value'][coord] = {}
                context['value'][coord].update(self._values[field])

        # Update context.error with this graph's errors
        for field in self.fields:
            for error_type in ["low", "high"]:
                error_field = f"error_{field}_{error_type}"
                if error_field in self._errors:
                    coord = field_to_coord.get(field)
                    if coord:
                        error_key = f"{coord}_{error_type}"
                        if error_key not in context['error']:
                            context['error'][error_key] = {}
                        context['error'][error_key].update(self._errors[error_field])

