def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    if level >= 1:
        d1 = d1.copy()
    diff = {}
    common_keys = set(d1.keys()) & set(d2.keys())
    for key in d1.keys():
        item = d1[key]
        if key not in d2:
            diff[key] = item
        elif not isinstance(item, dict) or not isinstance(d2[key], dict):
            if item != d2[key]:
                diff[key] = item
        else:
            sub_diff = difference(item, d2[key], level + 1)
            if sub_diff:
                diff[key] = sub_diff
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    diff = {}
    for key, val in d1.items():
        if key not in d2:
            diff[key] = val
        elif isinstance(val, dict):
            if level in (0, -1):
                diff_val = difference(val, d2[key], level - 1 if level != -1 else -1)
                if diff_val:
                    diff[key] = diff_val
            else:
                # level > 0, so we only go down level-1 more levels
                if level > 1:
                    diff_val = difference(val, d2[key], level - 1)
                    if diff_val:
                        diff[key] = diff_val
                # else level == 1, so we don't recurse, and if values are
                # both dicts but different, we include the whole value?
                # According to docs, for level 1, if a key is present in both
                # but has different values, include into difference.
                # So if val != d2[key], include val.
                # But we need to check for dict-ness? The docs say "has different values".
                # Simple equality check.
                if val != d2[key]:
                    diff[key] = val
        elif val != d2[key]:
            diff[key] = val
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    diff = {}
    for k, v in d1.items():
        if k not in d2:
            diff[k] = v
        else:
            if isinstance(v, dict) and isinstance(d2[k], dict):
                sub_diff = difference(v, d2[k], level - 1 if level != -1 else -1)
                if sub_diff:
                    diff[k] = sub_diff
            else:
                if v != d2[k]:
                    diff[k] = v
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 1:
        diff = {}
        for k, v in d1.items():
            if k not in d2 or k in d2 and d1[k] != d2[k]:
                diff[k] = v
        return diff
    else:
        diff = {}
        for k, v in d1.items():
            if k not in d2:
                diff[k] = v
            elif isinstance(v, dict):
                diff_sub = difference(v, d2[k], level + 1)
                if diff_sub:
                    diff[k] = diff_sub
            elif v != d2[k]:
                diff[k] = v
        return diff

def difference(d1, d2, level=-1):
    result = {}
    for k, v in d1.items():
        if k not in d2:
            result[k] = v
        else:
            if isinstance(v, dict) and isinstance(d2[k], dict):
                if level == -1 or level > 1:
                    sub_diff = difference(v, d2[k], level)
                    if sub_diff:
                        result[k] = sub_diff
                else:
                    if v != d2[k]:
                        result[k] = v
            else:
                if v != d2[k]:
                    result[k] = v
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != len(self._edges):
        raise ValueError("number of coordinates does not match number of bins")

    # check whether coordinate is inside edges
    if not all(self._edges[i][0] <= coord[i] < self._edges[i][1] for i in range(len(coord))):
        return

    index = tuple(np.searchsorted(self._edges[i], coord[i], side='right') - 1
                  for i in range(len(coord)))
    self._hist[index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    for v, left, right in zip(coord, self.left_edges, self.right_edges):
        if v < left or v >= right:
            return
    idx = tuple(self._index(coord, edges) for edges in zip(self.left_edges, self.right_edges))
    self.weight[idx] += weight

