def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for i, item in enumerate(observer_schema):
        if isinstance(item, dict):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            if last_applied_manifest[i] is None:
                last_applied_manifest[i] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[i], item, response[i] if i < len(response) else None
            )
        elif isinstance(item, list):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            if last_applied_manifest[i] is None:
                last_applied_manifest[i] = []
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i], item, response[i] if i < len(response) else []
            )
        else:
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            if last_applied_manifest[i] is None:
                if i < len(response):
                    last_applied_manifest[i] = response[i]
                else:
                    last_applied_manifest[i] = None

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for idx, (observer_el, response_el) in enumerate(zip(observer_schema, response)):
        if idx < len(last_applied_manifest):
            item = last_applied_manifest[idx]
        else:
            item = None

        if isinstance(observer_el, list):
            if item is None or not isinstance(item, list):
                item = []
                last_applied_manifest.extend([item] * (idx - len(last_applied_manifest) + 1))
                last_applied_manifest[idx] = item
            update_last_applied_manifest_list_from_resp(item, observer_el, response_el)
        elif isinstance(observer_el, dict):
            if item is None or not isinstance(item, dict):
                item = {}
                last_applied_manifest.extend([item] * (idx - len(last_applied_manifest) + 1))
                last_applied_manifest[idx] = item
            update_last_applied_manifest_dict_from_resp(item, observer_el, response_el)
        else:
            # observer_el is a primitive (str, int, float, bool, None)
            if item is None or not isinstance(item, type(observer_el)):
                last_applied_manifest.extend([observer_el] * (idx - len(last_applied_manifest) + 1))
                last_applied_manifest[idx] = observer_el

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field in observer_schema:
        if field not in last_applied_manifest:
            if isinstance(field, list):
                last_applied_manifest.append(update_last_applied_manifest_list_from_resp([], field, response))
            else:
                last_applied_manifest.append(field)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for i, schema_entry in enumerate(observer_schema):
        if i >= len(last_applied_manifest) or last_applied_manifest[i] is None:
            last_applied_manifest[i] = {} if isinstance(schema_entry, dict) else []
        if isinstance(schema_entry, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[i], schema_entry, response[i]
            )
        elif isinstance(schema_entry, list):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i], schema_entry, response[i]
            )

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not last_applied_manifest:
        return last_applied_manifest

    for field, value in observer_schema.items():
        if field not in last_applied_manifest:
            if field not in response:
                raise KeyError(field)
            if isinstance(value, dict):
                last_applied_manifest[field] = {}
            elif isinstance(value, list):
                last_applied_manifest[field] = []
            else:
                last_applied_manifest[field] = None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import krake.data.kubernetes as k8s

    manifest = app.spec.manifest
    if not hasattr(app, 'observer_schema'):
        app.observer_schema = {}

    for resource in manifest:
        resource_name = resource.name if hasattr(resource, 'name') else str(resource)
        if resource_name not in app.observer_schema:
            app.observer_schema[resource_name] = k8s.ObserverSchema.default_for_resource(resource)

    return app.observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    import json

    manifest = app.spec.get('manifest', {})
    if not manifest:
        return

    # Initialize the observer section if it doesn't exist
    if 'observer' not in app.spec:
        app.spec['observer'] = {}

    # Iterate over resources in the manifest
    for resource_name, resource_spec in manifest.items():
        # Skip if a custom observer schema is already defined for this resource
        if resource_name in app.spec['observer']:
            continue

        # Determine the kind of resource
        kind = resource_spec.get('kind', '')
        resource_type = resource_spec.get('type', 'Deployment')

        # Generate a default observer schema based on resource type
        if resource_type in ['Deployment', 'StatefulSet', 'DaemonSet']:
            default_observer = {
                'interval': 10,
                'timeout': 300,
                'checks': [
                    {
                        'name': 'availability',
                        'type': 'availability',
                        'threshold': 1,
                    }
                ]
            }
        elif resource_type == 'Service':
            default_observer = {
                'interval': 10,
                'timeout': 30,
                'checks': [
                    {
                        'name': 'endpoint_health',
                        'type': 'endpoint_health',
                        'path': '/healthz',
                        'timeout': 10,
                    },
                ]
            }
        else:
            # Default generic observer for other resource types
            default_observer = {
                'interval': 30,
                'timeout': 60,
                'checks': []
            }

        app.spec['observer'][resource_name] = default_observer

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for kind, resources in app.spec.manifest.resources.items():
        for name in resources:
            manifest = app.spec.manifest.resources[kind][name]
            if not manifest.get('observerSchema'):
                manifest['observerSchema'] = generate_default_observer_schema_by_kind(kind)

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not params:
        return sql, params
    if isinstance(params, dict):
        # Named placeholder style
        if self.in_style == 'named':
            return self._format_named(sql, params)
        else:
            # raise TypeError
            raise TypeError('params must be a dict if self.in_style is named')
    elif isinstance(params, (list, tuple)):
        # Positional placeholder style
        if self.in_style == 'positioned' or self.in_style == 'numeric':
            return self._format_positional(sql, params)
        else:
            raise TypeError('params must be a sequence if self.in_style is not named')
    else:
        raise TypeError('Invalid params type: {}'.format(type(params)))

def format(self, sql, params):
    if isinstance(params, dict):
        return self._format_dict(sql, params)
    elif isinstance(params, (list, tuple)):
        return self._format_seq(sql, params)
    else:
        raise TypeError("params must be a dict or a list or tuple")

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        path = os.path.abspath(path)

        if not os.path.exists(path):
            return False

        try:
            with open(os.path.join(path, 'inventory.json'), 'r') as inventory:
                data = json.load(inventory)

            if 'objectId' not in data:
                return False

            if 'type' not in data:
                return False

            if data['type'] != 'OCFL Inventory':
                return False

            if 'root' not in data:
                return False

            if 'manifest' not in data:
                return False

        except:  # pylint: disable=W0703
            return False

        return True

