def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not fixity:
            return

        if not isinstance(fixity, dict):
            raise ValueError('Invalid fixity block.')

        for md5, files in fixity.items():
            if not isinstance(md5, basestring):
                raise ValueError('Fixity block: checksum must be a string.')
            if not isinstance(files, (list, tuple)):
                raise ValueError('Fixity block: files must be a list.')
            for file in files:
                if isinstance(file, list):
                    file = file[0]
                if not isinstance(file, basestring):
                    raise ValueError('Fixity block: file must be a string.')
                if file not in manifest_files:
                    raise ValueError('Fixity block: file "%s" is not in the manifest.' % file)

