        else:
            word1 = words2
    else:
        words1 = ""
    # Configuration regex para suppl
    suppl_regex = r"(\s|([sS]\s)*\s*)((suppl|supp|aus|spe|sup|pr))(\s|\.?|)\s*"
    splitted = re.split(suppl_regex, words1)
    activ = False
    extra_params = []
    for word in splitted:
        if word['suppl'] is not None:
            activates = re.sub(r"\.", "", word["suppl"])
            if not activ:
                activ = True
                extra_params.append(word.get("number"))
            else:
                extra_params.append(word.get("number"))
            if word.get("number") == "1":
                extra_params[-1] = extra_params[-1] + "[suppl]"
            else:
                extra_params.append(str(word.get("number")))
    number = ""
    # Verifica se existe outro número (ex: 2-5 suppl or 25 suppl)
    if len(splitted) == 0 or not activ:
        number = re.search(regex_number, words1)["number"]
        if not re.search(r"^[0-9]*$|^[a-zA-Z*]+$", number):
            number = number.replace("-", "_")
    elif word1:
        number = re.search(regex_number, word1)["number"]
    if activ:
        number = (extra_params)
    elif number:
        number = str(number)
    return str(number), str(extra_params)

