def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if arg.func is And:
            for i, a in enumerate(arg.args):
                for b in arg.args[:i] + arg.args[i+1:]:
                    if a.equals(b):
                        result.append(a)
                        break
                    if a.equals(~b):
                        result.append(And(a, b))
                        break
        elif arg.func is Or:
            for i, a in enumerate(arg.args):
                for b in arg.args[:i] + arg.args[i+1:]:
                    if a.equals(b):
                        result.append(a)
                        break
                    if a.equals(~b):
                        result.append(Or(a, b))
                        break
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    results = []
    for i, arg in enumerate(args):
        if type(arg) is Or:
            if type(args[i-1]) is And:
                # A & (A | B) = A, A | (A & B) = A
                if args[i-1].args[0] in arg.args:
                    results.pop()
                    results.append(args[i-1].args[0])
                else:
                    results.append(arg)
            else:
                results.append(arg)
        elif type(arg) is And:
            if type(args[i-1]) is Or:
                # A | (A & B) = A, A & (A | B) = A
                if args[i-1].args[0] in arg.args:
                    results.pop()
                    results.append(args[i-1].args[0])
                else:
                    results.append(arg)
            else:
                results.append(arg)
        else:
            results.append(arg)
    return results

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Create new args list with possible absorption.
    # Thanks to travishathaway for the initial version of this function.
    from sympy import And, Or, Not

    has_And, has_Or = map(lambda c: type(c) in list(args), [And, Or])
    if not has_And or not has_Or:
        return list(args)

    new_args = []
    for i, a in enumerate(args):
        for b in args[i + 1:]:
            if isinstance(a, And) and isinstance(b, Or):
                # Use absorption law
                for c in a.args:
                    if c in b.args:
                        a = a.__class__(a.args).doit()
                        b = b.__class__(b.args).doit()
                        new_args.append(And(a, b))
                        break
            elif isinstance(a, Or) and isinstance(b, And):
                # Use absorption law
                a, b = b, a
                if isinstance(a, And) and isinstance(b, Or):
                    for c in a.args:
                        if c in b.args:
                            a = a.__class__(a.args).doit()
                            b = b.__class__(b.args).doit()
                            new_args.append(Or(a, b))
                            break

            else:
                continue

            else:
                for c in args:
                    if c != a and c != b:
                        if isinstance(c, Or) and isinstance(a, And) or isinstance(c, And) and isinstance(a, Or):
                            a = a.__class__(a.args).doit()
                            c = c.__class__(c.args).doit()
                            new_args.append(type(c)(a, c))
                            break

    return args

def _fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if not dt.tzinfo:
            dt = dt.replace(tzinfo=self)

        dt_dst = dt.dst()
        if not dt_dst:
            return dt - self.utcoffset(dt)

        # Results in a list of possible datetimes in UTC
        deltas = [dt - self.utcoffset(dt), dt - self.utcoffset(dt) + dt_dst]

        for _dt in deltas:
            if _dt.tzinfo is None:
                _dt = _dt.replace(tzinfo=pytz.utc)
            else:
                _dt = _dt.astimezone(pytz.utc)

        try:
            delta_from_default = deltas[0] - deltas[self._utc_inverse_localize(dt.utctimetuple())]
        except IndexError:
            delta_from_default = timedelta(0)

        # It's unambiguous, or it's ambiguous and the user wants the default
        if delta_from_default == timedelta(0):
            return deltas[0].replace(tzinfo=pytz.utc)

        # It's ambiguous, and the user wants the other one
        return deltas[1].replace(tzinfo=pytz.utc)

