    def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        root = self.get_root()
        if root is None:
            return (num_objects, good_objects)
        visited = set()
        def _dfs(node_id, node):
            nonlocal num_objects, good_objects
            if node_id in visited:
                if show_warnings:
                    print(f"Warning: Cyclic dependency detected at node {node_id}")
                return
            visited.add(node_id)
            num_objects += 1
            node_is_valid = True
            if check_digests and hasattr(node, 'digest'):
                node_is_valid = node.validate_digest()
            if validate_objects:
                if not node.validate():
                    node_is_valid = False
            if node_is_valid:
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Warning: Node {node_id} failed validation")
            for child_id in node.children:
                child = self.get_object(child_id)
                if child is None:
                    if show_warnings:
                        print(f"Warning: Child node {child_id} not found")
                    continue
                _dfs(child_id, child)
        _dfs(root.id, root)
        return (num_objects, good_objects)
