def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "0"

    try:
        # Try to parse as simple integer
        num = int(version)
        next_num = num + 1
        return str(next_num)
    except ValueError:
        # Handle version strings like "1.0", "1.0.1", etc.
        parts = version.split('.')
        if not parts:
            return "0"

        # Process from right to left, incrementing the first non-9 part
        # and resetting subsequent parts to 0
        i = len(parts) - 1
        while i >= 0:
            part = parts[i]
            # Extract digits only for processing, but preserve leading zeros info
            # Actually, let's assume each component is an integer string
            try:
                val = int(part)
                if val < 9:
                    parts[i] = str(val + 1)
                    # Reset all lower parts to '0'
                    for j in range(i + 1, len(parts)):
                        parts[j] = '0'
                    return '.'.join(parts)
                else:
                    # If it's 9, set to 0 and continue to next higher part
                    parts[i] = '0'
                    i -= 1
            except ValueError:
                # If any part is not a simple integer, we might just return version + ".1" or similar
                # But the prompt implies numerical versions. Let's assume numeric components.
                break

        # If all parts were 9 (e.g., "9" or "9.9"), prepend a new level
        # But typically version strings just increment the least significant digit that can be incremented.
        # If we fell through the loop, it means all were 9.
        # Example: "9" -> "10", "1.9" -> "1.10"
        # Let's try a simpler approach: treat the whole string after last dot or the whole thing if no dot
        pass

    # Alternative robust approach for dot-separated numeric versions:
    # Find the rightmost numeric component that is not max (or treat max as wrap around to create new leaf)
    # Actually, the simplest interpretation of "next version" for strings like "1.0.0" is incrementing the last part.
    # For "1.9", it becomes "1.10".
    # For "9", it becomes "10".

    # Let's rewrite the logic to be cleaner
    if '.' in version:
        parts = version.split('.')
        # Increment the last part
        last_part = parts[-1]
        try:
            last_num = int(last_part)
            parts[-1] = str(last_num + 1)
            return '.'.join(parts)
        except ValueError:
            # If the last part is not a number, try to append .1 or similar?
            # Given the docstrings in examples are simple, let's assume numeric
            return version + ".1"
    else:
        try:
            num = int(version)
            return str(num + 1)
        except ValueError:
            return version + "1"

