    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode

    merged = {}

    for key, value in nodes:
        if key.value in merged:
            existing_value = merged[key.value]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                # Deep merge: recursively merge the inner nodes
                existing_inner = deep_merge_nodes(existing_value.value)
                incoming_inner = deep_merge_nodes(value.value)
                # Merge the two lists of inner tuples
                combined_inner = list(existing_inner)
                for inner_key, inner_value in incoming_inner:
                    # Check if inner_key already exists in combined_inner
                    found = False
                    for i, (ck, cv) in enumerate(combined_inner):
                        if ck.value == inner_key.value:
                            # Update this entry
                            combined_inner[i] = (inner_key, inner_value)
                            found = True
                            break
                    if not found:
                        combined_inner.append((inner_key, inner_value))
                merged[key.value] = value.__class__(value.tag, combined_inner, flow_style=None)
            else:
                # Non-mapping nodes: last value wins
                merged[key.value] = value
        else:
            merged[key.value] = value

    # Convert back to list of tuples, preserving order
    result = []
    for original_key, original_value in nodes:
        if original_key.value in merged:
            if original_value is merged[original_key.value]:
                result.append((original_key, merged[original_key.value]))
            elif isinstance(merged[original_key.value], type(original_value)) and merged[original_key.value] is not original_value:
                # Check if we need to create a new node or use existing
                # For mapping nodes that were merged, we need to create new MappingNode
                if isinstance(original_value, MappingNode) and isinstance(merged[original_key.value], MappingNode):
                    # Use the merged value
                    result.append((original_key, merged[original_key.value]))
                else:
                    result.append((original_key, merged[original_key.value]))

    # Remove duplicates - only keep first occurrence of each key
    seen = set()
    final_result = []
    for key, value in result:
        if key.value not in seen:
            seen.add(key.value)
            final_result.append((key, value))

    return final_result
