def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    from ruamel.yaml.nodes import MappingNode, ScalarNode
    from ruamel.yaml.comments import CommentedMap

    merged = {}
    for key, value in nodes:
        if isinstance(key, ScalarNode):
            key_str = key.value
        else:
            key_str = key

        if key_str in merged:
            existing_value = merged[key_str]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                # Deep merge MappingNodes
                merged[key_str] = _deep_merge_mapping_nodes(existing_value, value)
            else:
                # Last value wins for non-MappingNode values
                merged[key_str] = value
        else:
            merged[key_str] = value

    return list(merged.items())


def _deep_merge_mapping_nodes(node1, node2):
    """
    Recursively deep merge two MappingNodes.
    If keys collide with non-MappingNode values, the last value wins.
    """
    from ruamel.yaml.nodes import MappingNode, ScalarNode
    from ruamel.yaml.comments import CommentedMap

    result = MappingNode(tag=node1.tag, value=[])
    # Preserve the style from the first mapping node
    result.style = node1.style if hasattr(node1, 'style') else None

    # Start with a copy of node1
    result.value = list(node1.value)

    # Build a dict of existing values in result for quick lookup
    # Key is the string value of the ScalarNode, or the node itself if not a ScalarNode
    existing = {}
    for k, v in result.value:
        if isinstance(k, ScalarNode):
            key_str = k.value
        else:
            key_str = k
        existing[key_str] = (k, v)

    # Now merge node2
    for k2, v2 in node2.value:
        if isinstance(k2, ScalarNode):
            k2_str = k2.value
        else:
            k2_str = k2

        if k2_str in existing:
            k_existing, v_existing = existing[k2_str]
            if isinstance(v_existing, MappingNode) and isinstance(v2, MappingNode):
                # Deep merge
                merged_val = _deep_merge_mapping_nodes(v_existing, v2)
                # Replace the value in the result list
                # Find the index of the tuple
                for i, (treating_k, treating_v) in enumerate(result.value):
                    k_treating_str = treating_k.value if isinstance(treating_k, ScalarNode) else treating_k
                    if k_treating_str == k2_str:
                        result.value[i] = (k_existing, merged_val)
                        break
            else:
                # Last value wins
                for i, (treating_k, treating_v) in enumerate(result.value):
                    k_treating_str = treating_k.value if isinstance(treating_k, ScalarNode) else treating_k
                    if k_treating_str == k2_str:
                        result.value[i] = (k_existing, v2)
                        break
        else:
            # Add new key-value pair
            result.value.append((k2, v2))
            existing[k2_str] = (k2, v2)

    return result

