def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        for sc in c.__subclasses__():
            if sc not in seen:
                queue.add(sc)

    seen.remove(cls)
    return seen

