def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    # POSIX-like: split on whitespace, respecting quotes
    if platform == 1:
        return shlex.split(s)
    # Windows/CMD-like: more permissive, split on whitespace but keep quotes-
    # containing spaces intact, handle escaping with backslash
    if platform == 0:
        # Use a regex that matches:
        # 1. Quoted strings (single or double quotes)
        # 2. Unquoted sequences of non-whitespace characters
        pattern = r'"[^"]*"|\'[^\']*\'|\\.|[^\s\\'"|]+'
        return re.findall(pattern, s)
    raise ValueError(f"Unknown platform: {platform}")

