        elif archive_path.endswith(".zip"):
            subprocess.run(["unzip", archive_path, "-d", tmp_dir], check=True)
        else:
            raise ValueError("Unsupported archive format")

        # If the archive contains a single top-level directory, use that as the repo base
        items = os.listdir(tmp_dir)
        if len(items) == 1:
            extracted_path = os.path.join(tmp_dir, items[0])
            if os.path.isdir(extracted_path):
                tmp_dir = extracted_path

        # Construct and return the file URL
        return "file://" + os.path.abspath(tmp_dir)
