def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(['git', 'ls-files', '--others', '--ignored', '--exclude-standard'], stderr=subprocess.STDOUT).decode('utf-8')
        files = [line.strip() for line in output.split('\n') if line.strip()]
        ignored_files = []
        for file in files:
            try:
                subprocess.check_output(['git', 'check-ignore', '-q', file], stderr=subprocess.STDOUT)
                ignored_files.append(file)
            except subprocess.CalledProcessError:
                pass
        ignored_files = sorted(ignored_files)
        return ','.join(ignored_files)
    except Exception as e:
        return ''
