def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    args = [str(arg) for arg in args]
    cmd = [str(cmd) for cmd in commands] + args
    if verbose and not hide_stderr:
        print("run_command: calling {:s}".format(" ".join(cmd)))

    if env and not hide_stderr:
        for k, v in env.items():
            print("ENVIRONMENT:")
            print("{}.format(k) = {:s}".format(v))

    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
    )
    out, err = proc.communicate()
    if proc.returncode:
        raise RuntimeError("run_command: SyntaxError in {:s}\nstderr: {:s}".format(" ".join(cmd), err.decode("UTF-8")))
    return out.decode("UTF-8")

