def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for child, _, parent in graph:
        if prop in graph.subjects(rdflib.RDFS.subClassOf):
            continue
        if child not in graph.objects(child, prop):
            roots.add(child)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for child, parent in graph.predicate_objects(prop):
        if parent not in roots:
            find_roots(graph, prop, roots)
    if len(graph.predicate_subjects(prop)) == 0:
        return set()
    return set(roots)

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    for s, p, o in graph:
        if p == prop:
            for parent in graph.transitive_objects(o, prop_rdf_type=None):
                roots.discard(parent)
    for s, p, o in graph:
        if p == prop:
            if o not in roots:
                roots.add(o)
    return roots

