            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        # Get all possible protocol versions from the CLASS attribute, if it exists
        if not hasattr(cls, 'BOLT_HANDLERS'):
            return {}
        all_versions = cls.BOLT_HANDLERS

        if protocol_version is not None:
            # Ensure it's a tuple
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple or None.")
            # Check if the provided version is supported
            if protocol_version in all_versions:
                return {protocol_version: all_versions[protocol_version]}
            else:
                return {}
        else:
            # Return all supported versions
            return dict(all_versions)
