        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """

        if other is None:
            if hasattr(self, "fields"):
                fields = self.fields
                if len(fields) > 1:
                    last_field = fields[-1]
                    coord_indices = self.coordinates[last_field.name]
                    if len(coord_indices) > 0:
                        coord_index = coord_indices[-1]
                        if coord_index in self.data:
                            return self.data[coord_index][0]
                elif len(fields) == 1:
                    field = fields[0]
                    coord_indices = self.coordinates[field.name]
                    if len(coord_indices) > 0:
                        coord_index = coord_indices[-1]
                        if coord_index in self.data:
                            return self.data[coord_index][0]
            return None
        else:
            if other == 0:
                raise self.LenaValueError("cannot scale to zero")
            if hasattr(self, "fields"):
                fields = self.fields
                if len(fields) > 1:
                    last_field = fields[-1]
                    coord_indices = self.coordinates[last_field.name]
                    if len(coord_indices) > 0:
                        coord_index = coord_indices[-1]
                        if coord_index in self.data:
                            data_value = self.data[coord_index][0]
                            if data_value == 0:
                                raise self.LenaValueError("cannot rescale zero")
                            self.data[coord_index] = (other,)
                        for error_name in self.coordinates:
                            if error_name in self.fields_by_coordinate.get(coord_index, []):
                                pass
                elif len(fields) == 1:
                    field = fields[0]
                    coord_indices = self.coordinates[field.name]
                    if len(coord_indices) > 0:
                        coord_index = coord_indices[-1]
                        if coord_index in self.data:
                            data_value = self.data[coord_index][0]
                            if data_value == 0:
                                raise self.LenaValueError("cannot rescale zero")
                            self.data[coord_index] = (other,)

def scale(self, other=None):
    if other is None:
        return self._scale
    if not self._scale or self._scale == 0:
        raise ValueError("Cannot rescale a graph with unknown or zero scale.")
    scale_ratio = other / self._scale
    self._scale = other
    if hasattr(self, 'fields'):
        n_coords = len(self.fields)
        if n_coords > 0:
            last_coord_index = n_coords - 1
            for i in range(n_coords):
                coord = getattr(self, 'field_%d' % i)
                if i == last_coord_index:
                    coord *= scale_ratio
                err = getattr(self, 'error_%d' % i)
                if i == last_coord_index:
                    err *= scale_ratio
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.content
    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.x_left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.x_right
    elif get_coordinate == "middle":
        get_coordinate = lambda bin_: (bin_.x_left + bin_.x_right) / 2.0
    elif callable(get_coordinate):
        pass
    else:
        raise ValueError(f"Invalid get_coordinate {get_coordinate}")
    if scale is True:
        scale = hist.scale
    if scale is not None and not isinstance(scale, (int, float)):
        if scale == 'linear':
            scale = 1.0
        elif scale == 'log':
            scale = None
        else:
            raise ValueError(f"Invalid scale {scale}")
    points = []
    for bin_ in hist:
        x = get_coordinate(bin_)
        y = make_value(bin_)
        if isinstance(y, (int, float)):
            point = (float(x), float(y))
        else:
            point = (float(x), ) + tuple(float(val) for val in y)
        points.append(point)
    graph = Graph(field_names=field_names, scale=scale)
    graph.add_points(points)
    return graph

