def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: A tuple of base classes.
    :param explicit_mc: An explicit metaclass, if specified.
    :returns: The determined metaclass.
    :rtype: type
    """
    if explicit_mc:
        return explicit_mc
    if not bases:
        return type
    metaclass = type
    for base in bases:
        if isinstance(base, type):
            base_metaclass = type(base)
            if issubclass(metaclass, base_metaclass):
                metaclass = base_metaclass
    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclass = None
    for base in bases:
        if base.__class__ is type:
            metaclass = base.__class__
        else:
            if metaclass is None:
                metaclass = base.__class__
            else:
                if not issubclass(metaclass, base.__class__):
                    raise TypeError(
                        "metaclass conflict: "
                        "the metaclass of a derived class must be a "
                        "(non-strict) subclass of the metaclasses of all its bases"
                    )
    if explicit_mc is not None:
        if not issubclass(explicit_mc, metaclass):
            raise TypeError(
                "metaclass conflict: "
                "the metaclass of a derived class must be a "
                "(non-strict) subclass of the metaclasses of all its bases"
            )
        metaclass = explicit_mc
    if metaclass is None:
        metaclass = type
    return metaclass

