def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
       return explicit_mc
    metaclasses = set(b.__class__ for b in bases)
    if not metaclasses:
        return type
    # This mimics the logic in Types.py,
    # which checks to be all of the type hierarchy is fine before updating it
    for mc in metaclasses:
        if mc is type:
            continue
        for other in metaclasses:
            if mc is not other and issubclass(mc, other):
                return mc
    raise TypeError('inconsistent metatypes' % (list(metaclasses)))

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If there's an explicit metaclass, use it if it's compatible
    if explicit_mc is not None:
        # Check if explicit_mc is a metaclass
        try:
            # An explicit metaclass must be a metaclass or a subclass of type
            if not (isinstance(explicit_mc, type) and issubclass(explicit_mc, type)):
                raise TypeError("Explicit __metaclass__ must be a metaclass")
            return explicit_mc
        except TypeError:
            # Fall through to compute from bases
            pass

    # No explicit metaclass or it was incompatible, compute from bases
    if not bases:
        # No bases, use the default metaclass (type, or a custom global metaclass)
        # For simplicity here, assume default is type, but in a full implementation
        # we'd check for a global __metaclass__
        return type

    # Compute the most-derived metaclass
    # Start with type as the default metaclass
    winner = type

    for base in bases:
        # Get the metaclass of each base
        try:
            base_mc = type(base)
        except TypeError:
            # If base is not a class, skip it (e.g., it might be a string or other object)
            continue

        # Compare winner and base_mc
        if isinstance(base_mc, type) and issubclass(base_mc, winner):
            winner = base_mc

    return winner

