def isoparse(self, dt_str):
    if isinstance(dt_str, bytes):
        dt_str = dt_str.decode('ascii')
    match = _iso_8601_regex.match(dt_str)
    if not match:
        raise ValueError('Cannot parse ISO date')
    bits = match.groupdict()
    year_and_month = bits['year_month']
    year, month = 0, 1
    if year_and_month:
        year, month = self._parse_year_month(year_and_month)
    week = bits['week']
    if week:
        year, week = self._parse_year_week(week)
    day = bits['day']
    if day:
        self._parse_year_day(year, month, day)
    hour, minute, second, microsecond = self._parse_time(bits)
    tzinfo = self._parse_tzinfo(bits['tz'], bits['tz_colon'])
    return datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo)

def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    # Raise if we do not get a string or something like a stream.
    if not isinstance(timestr, (str, PY3)):
        raise TypeError("ParserError: expected string or character stream, "
                        "instead got type '%s'" % type(timestr).__name__)

    if timestr is None:
        raise TypeError("ParserError: timestr must not be None")

    if default is None:
        default = datetime.datetime.now(tz=self._tzinfos or None).replace(tzinfo=None)

    res, skipped_tokens = self._parse(timestr, **kwargs)
    if res:
        res_tup = res.timetuple()
        kw = "year", "month", "day", "hour", "minute", "second"

        period = res.period
        ampm = res.ampm
        tzinfo = res.tzinfo
        tzoffset = res.tzoffset

        kwargs = dict(zip(kw, res_tup[:6]))
        default_kwargs = default.timetuple() + default.tzinfo
        kwargs = kwargs + dict(zip(kw, default_kwargs))

        kwargs["year"] = min(9999, max(1, kwargs["year"]))
        kwargs["month"] = min(12, max(1, kwargs["month"]))
        kwargs["day"] = min(31, max(1, kwargs["day"]))
        kwargs["hour"] = min(23, max(0, kwargs["hour"]))
        kwargs["minute"] = min(59, max(0, kwargs["minute"]))
        kwargs["second"] = min(59, max(0, kwargs["second"]))
        kwargs["microsecond"] = res.microsecond

        if ignoretz:
            tz = None
        else:
            tz = tzinfo
            if tzoffset is not None:
                tz = make_tzoffset(tzoffset)
            elif tz is None:
                # Prevent using the default timezone if one
                # shouldn't be found in the parsed string.
                tz = self._tzinfos
                if tz is not None:
                    if callable(tz):
                        tz = tz(period, ampm)
                    else:
                        tz = tzinfos.get(period, None)
                else:
                    tz = self._default_tz

        try:
            retval = datetime.datetime(**kwargs)
        except ValueError:
            raise ParserError("Invalid date string or format: %(timestr)r",
                              timestr=timestr)

        if res.fuzzy_with_tokens:
            return (retval, skipped_tokens), skipped_tokens
        else:
            return retval
    else:
        raise ParserError("Invalid date string or format: %(timestr)r",
                          timestr=timestr)

def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a :class:`datetime.datetime` object.

    :param timestr:
        Any date/time string using the supported formats.

    :param default:
        The default datetime object, if this is a datetime object and not
        ``None``, elements specified in ``timestr`` replace elements in the
        default object.

    :param ignoretz:
        If set ``True``, time zones in parsed strings are ignored and a
        naive :class:`datetime.datetime` object is returned.

    :param tzinfos:
        Additional time zone names / aliases which may be present in the
        string. This argument maps time zone names (and optionally offsets
        from those time zones) to time zones. This parameter can be a
        dictionary with timezone aliases mapping time zone names to time
        zones or a function taking two parameters (``tzname`` and
        ``tzoffset``) and returning a time zone.

        The timezones to which the names are mapped can be an integer
        offset from UTC in seconds or a :class:`tzinfo` object.

        .. doctest::
           :options: +NORMALIZE_WHITESPACE

            >>> from dateutil.parser import parse
            >>> from dateutil.tz import gettz
            >>> tzinfos = {"BRST": -7200, "CST": gettz("America/Chicago")}
            >>> parse("2012-01-19 17:21:00 BRST", tzinfos=tzinfos)
            datetime.datetime(2012, 1, 19, 17, 21, tzinfo=tzoffset(u'BRST', -7200))
            >>> parse("2012-01-19 17:21:00 CST", tzinfos=tzinfos)
            datetime.datetime(2012, 1, 19, 17, 21,
                              tzinfo=tzfile('/usr/share/zoneinfo/America/Chicago'))

        This parameter is ignored if ``ignoretz`` is set.

    :param \\*\\*kwargs:
        Keyword arguments as passed to ``_parse()``.

    :return:
        Returns a :class:`datetime.datetime` object or, if the
        ``fuzzy_with_tokens`` option is ``True``, returns a tuple, the
        first element being a :class:`datetime.datetime` object, the second
        a tuple containing the fuzzy tokens.

    :raises ParserError:
        Raised for invalid or unknown string format, if the provided
        :class:`tzinfo` is not in a valid format, or if an invalid date
        would be created.

    :raises TypeError:
        Raised for non-string or character stream input.

    :raises OverflowError:
        Raised if the parsed date exceeds the largest valid C integer on
        your system.
    """
    if not isinstance(timestr, (str, datetime.date, datetime.datetime)):
        raise TypeError("Parser must be a string or character stream, not %s" % type(timestr).__name__)

    if isinstance(timestr, datetime.datetime):
        dt = timestr
        if default and default.tzinfo:
            dt = dt.replace(tzinfo=default.tzinfo)
        return dt
    elif isinstance(timestr, datetime.date):
        dt = datetime.datetime(timestr.year, timestr.month, timestr.day)
        if default and default.tzinfo:
            dt = dt.replace(tzinfo=default.tzinfo)
        return dt

    res, skip_tokens = self._parse(timestr, **kwargs)

    if res is None:
        raise ParserError("Unknown string format: %s", timestr)

    if len(res) == 0:
        raise ParserError("Unable to parse date string: %s", timestr)

    if len(res) == 1:
        if res[0].hasattr('year'):
            pass  # Already a datetime object
        else:
            raise ParserError("Unable to parse date string: %s", timestr)

    retvals = []
    if res[0].hasattr('year'):
        retvals.append(res[0])
    else:
        if default:
            retvals.append(default)
        else:
            now = datetime.datetime.now()
            retvals.append(now)

    # Adjust the default values with the parsed values
    for i, val in enumerate(res):
        if i == 0:
            continue
        if val is not None:
            if i == 1:
                retvals[0] = retvals[0].replace(month=val)
            elif i == 2:
                retvals[0] = retvals[0].replace(day=val)
            elif i == 3:
                retvals[0] = retvals[0].replace(hour=val)
            elif i == 4:
                retvals[0] = retvals[0].replace(minute=val)
            elif i == 5:
                retvals[0] = retvals[0].replace(second=val)
            elif i == 6:
                retvals[0] = retvals[0].replace(microsecond=val)
            elif i == 7:
                # Timezone
                if not ignoretz:
                    if tzinfos is not None:
                        if callable(tzinfos):
                            tzinfos = tzinfos(val, 0)
                        else:
                            tzinfos = tzinfos.get(val)
                    else:
                        # Try to parse the timezone string
                        try:
                            tz = self._parser.parse_timezone(val)
                        except (ValueError, AttributeError):
                            tz = None
                    if tzinfos:
                        retvals[0] = retvals[0].replace(tzinfo=tzinfos)
                    elif tz:
                        retvals[0] = retvals[0].replace(tzinfo=tz)
                    else:
                        # If no timezone info could be determined, keep it naive or apply default
                        if default and default.tzinfo:
                            retvals[0] = retvals[0].replace(tzinfo=default.tzinfo)

    retval = retvals.pop(0)

    if kwargs.get('fuzzy_with_tokens'):
        return retval, skip_tokens
    else:
        return retval

