def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    if not tag.startswith('#'):
        return False
    if len(tag) > 50:
        return False
    # Check if tag contains only valid characters (alphanumeric, hyphens, underscores, and #)
    for char in tag[1:]:
