def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        parsed = json.loads(document)
        if "hcard_url" in parsed:
            return {
                "hcard_url": parsed["hcard_url"],
                "expiring_at": parsed.get("expiration"),
            }
        else:
            raise KeyError("hcard_url missing in JSON webfinger")
    except ValueError:  # JSON parse failed, try XRD
        parser = etree.XMLParser(remove_blank_text=True)
        root = etree.fromstring(document.encode(), parser)
        hcard_link = root.find(".//link[@rel='http://lists.w3.org/gh/groups/"]
        # Fallback: look for the hcard rel which can vary
        results = root.xpath("//link[@rel='http://home.gna.org/rel/hcard#/']")
        if results:
            href = results[0].get('href')
            return {"hcard_url": href}
        # Another possible rel
        results = root.xpath("//link[@rel='http://home.gna.org/rel/hcard.json#/']")
        if results:
            href = results[0].get('href')
            return {"hcard_url": href}
        # Try to find any hcard-like link
        for link in root.findall('.//link'):
            rel = link.get('rel')
            if 'hcard' in rel:
                return {"hcard_url": link.get('href')}
    return None
