def _get_conditionally_required_args(self, command_name, options_spec,
                                     args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        required_when = option.get('required_when', None)
        if required_when is None:
            continue
        if isinstance(required_when, (list, tuple)):
            # Check if all specified arguments are present in args
            if all(arg_name in args for arg_name in required_when):
                matched_args.append(option['name'])
        else:
            # Check if a single specified argument is present in args
            if required_when in args:
                matched_args.append(option['name'])
    return matched_args

def _get_conditionally_required_args(self, command_name, options_spec,
                                     args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    optional_args = []
    for option_spec in options_spec:
        if 'required_when' not in option_spec:
            continue
        required_when = option_spec.get('required_when')
        if command_name in required_when:
            for arg in args:
                if option_spec.get('arg') in args:
                    optional_args.append(option_spec.get('arg'))
    return optional_args

