    def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Iterate over each parameter in the spec
        for param_key, param_spec in self.spec.items():
            # Extract the expected length for this argument
            expected_length = param_spec.get('length', None)
            if expected_length is None:
                continue

            # Get the value provided for this argument
            arg_value = args.get(param_key)
            if arg_value is None:
                continue
            if hasattr(arg_value, '__len__'):
                arg_len = len(arg_value)
            elif isinstance(arg_value, str):
                arg_len = len(arg_value)
            else:
                # If not a container with length, skip or you can raise error
                continue

            if arg_len > expected_length:
                # Format the exception message using the known index
                raise ValueError(
                    "Argument '{}' length {} exceeds the specified maximum length of {}.".format(
                        param_key,
                        arg_len,
                        expected_length
                    )
                )
