     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    command = ["ansible-playbook"] + cli_args

    # Prepare extra-vars
    if vars_dict:
        extra_vars = []
        for key, value in vars_dict.items():
            if isinstance(value, (list, dict)):
                extra_vars.append(f"{key}='{json.dumps(value)}'")
            else:
                extra_vars.append(f"{key}='{value}'")
        command.extend(["--extra-vars", " ".join(extra_vars)])

    # Prepare connection settings
    if ir_workspace:
        if hasattr(ir_workspace, 'ansible_host') and ir_workspace.ansible_host:
            command.extend(["-i", f"{ir_workspace.ansible_host},"])
        if hasattr(ir_workspace, 'ansible_user') and ir_workspace.ansible_user:
            command.extend(["-u", ir_workspace.ansible_user])
        if hasattr(ir_workspace, 'ansible_password') and ir_workspace.ansible_password:
            command.extend(["-k"])  # Prompt for password
        if hasattr(ir_workspace, 'ansible_become') and ir_workspace.ansible_become:
            command.extend(["-b"])  # Use become

    if ir_plugin:
        if hasattr(ir_plugin, 'ansible_dir'):
            command.extend(["--playbook-dir", ir_plugin.ansible_dir])

    logger.debug("Executing playbook command: %s", " ".join(command))
    result = subprocess.run(command, capture_output=True, text=True)

    if result.returncode != 0:
        logger.error("Ansible command failed: %s", result.stderr)
        raise RuntimeError(f"Ansible command failed: {result.stderr}")

    return result.stdout
